mapper.select:
SELECT n.public_notice_id, n.category_code, n.title, n.is_pinned, n.publish_start_dttm, creator.name AS created_by_name, n.updated_dttm FROM public_notice n JOIN member creator ON creator.member_id = n.created_by_member_id WHERE n.status_code IN ('SCHEDULED', 'PUBLISHED') AND n.publish_start_dttm <= #{currentDttm} AND (n.publish_end_dttm IS NULL OR n.publish_end_dttm > #{currentDttm}) AND n.deleted_dttm IS NULL
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.body LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY n.is_pinned DESC, n.publish_start_dttm DESC, n.public_notice_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT n.public_notice_id, n.category_code, n.title, n.status_code, n.is_pinned, n.publish_start_dttm, n.publish_end_dttm, updater.name AS updated_by_name, n.updated_dttm FROM public_notice n JOIN member updater ON updater.member_id = n.updated_by_member_id WHERE n.deleted_dttm IS NULL
AND n.status_code = #{status}
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.body LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY n.updated_dttm DESC, n.public_notice_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.insert:
INSERT INTO public_notice (
    category_code, title, body, status_code, is_pinned,
    publish_start_dttm, publish_end_dttm, created_by_member_id,
    updated_by_member_id, published_by_member_id
) VALUES (
    #{categoryCode}, #{title}, #{body}, #{status}, #{pinned},
    #{publishStartDttm}, #{publishEndDttm}, #{createdByMemberId},
    #{updatedByMemberId}, #{publishedByMemberId}
)

INSERT INTO public_notice_attachment (
    public_notice_id, stored_file_id, display_order
) VALUES (
    #{publicNoticeId}, #{storedFileId}, #{displayOrder}
)

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM public_notice_attachment a
    JOIN public_notice n ON n.public_notice_id = a.public_notice_id
    WHERE a.public_notice_id = #{publicNoticeId}
      AND a.stored_file_id = #{storedFileId}
      AND n.status_code IN ('SCHEDULED', 'PUBLISHED')
      AND n.publish_start_dttm <= #{currentDttm}
      AND (n.publish_end_dttm IS NULL OR n.publish_end_dttm > #{currentDttm})
      AND n.deleted_dttm IS NULL
)
